import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/realtor-final111-20261019';const live=JSON.parse(await fs.readFile(dir+'/live-status.json'));const plan=JSON.parse(await fs.readFile(dir+'/plan.json'));const touches=await db('market_touches',{contact_id:'in.('+plan.plans.map(p=>p.contact_id).join(',')+')',direction:'eq.outbound',select:'id,contact_id,notes,metadata',limit:'1000'});const missing=live.jobs.filter(j=>!touches.some(t=>t.contact_id===j.contact_id&&t.metadata?.twilioSid===j.provider_sid));if(live.jobs.length!==111||live.jobs.some(j=>j.status!=='sent'||!j.provider_sid)||missing.length)throw Error('Receipt verification incomplete');const result={at:new Date().toISOString(),sent:111,unique_numbers:new Set(plan.plans.map(p=>p.phone)).size,crm_receipts_verified:111,remaining_queued:0,delivery_counts:live.summary.counts,worker:JSON.parse(await fs.readFile(dir+'/worker-status.json'))};await fs.writeFile(dir+'/closeout.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
